namespace MiniPharmacie.Data.Database;

internal static class Schema
{
    public const string V1 = """
CREATE TABLE IF NOT EXISTS SchemaVersions (Version INTEGER PRIMARY KEY, AppliedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Roles (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE CHECK(length(Name)>0));
CREATE TABLE IF NOT EXISTS Users (Id INTEGER PRIMARY KEY, RoleId INTEGER NOT NULL REFERENCES Roles(Id), Username TEXT NOT NULL UNIQUE, PasswordHash TEXT NOT NULL, IsActive INTEGER NOT NULL DEFAULT 1 CHECK(IsActive IN (0,1)), CreatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Categories (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, IsActive INTEGER NOT NULL DEFAULT 1 CHECK(IsActive IN (0,1)));
CREATE TABLE IF NOT EXISTS Products (Id INTEGER PRIMARY KEY, CategoryId INTEGER REFERENCES Categories(Id), Code TEXT NOT NULL UNIQUE, Name TEXT NOT NULL, Unit TEXT NOT NULL DEFAULT 'unité', Barcode TEXT UNIQUE, SalePriceMinor INTEGER NOT NULL CHECK(SalePriceMinor>=0), CostPriceMinor INTEGER NOT NULL DEFAULT 0 CHECK(CostPriceMinor>=0), ReorderLevel INTEGER NOT NULL DEFAULT 0 CHECK(ReorderLevel>=0), IsActive INTEGER NOT NULL DEFAULT 1 CHECK(IsActive IN (0,1)));
CREATE TABLE IF NOT EXISTS Suppliers (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, Phone TEXT, Email TEXT, Address TEXT, IsActive INTEGER NOT NULL DEFAULT 1 CHECK(IsActive IN (0,1)));
CREATE TABLE IF NOT EXISTS Receipts (Id INTEGER PRIMARY KEY, SupplierId INTEGER NOT NULL REFERENCES Suppliers(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), Reference TEXT NOT NULL UNIQUE, ReceivedAt TEXT NOT NULL, Notes TEXT);
CREATE TABLE IF NOT EXISTS Lots (Id INTEGER PRIMARY KEY, ProductId INTEGER NOT NULL REFERENCES Products(Id), ReceiptId INTEGER REFERENCES Receipts(Id), LotNumber TEXT NOT NULL, ExpiryDate TEXT, QuantityReceived INTEGER NOT NULL CHECK(QuantityReceived>=0), QuantityOnHand INTEGER NOT NULL CHECK(QuantityOnHand>=0), CostPriceMinor INTEGER NOT NULL CHECK(CostPriceMinor>=0), UNIQUE(ProductId,LotNumber));
CREATE TABLE IF NOT EXISTS StockMovements (Id INTEGER PRIMARY KEY, ProductId INTEGER NOT NULL REFERENCES Products(Id), LotId INTEGER REFERENCES Lots(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), MovementType TEXT NOT NULL CHECK(MovementType IN ('RECEPTION','VENTE','RETOUR','AJUSTEMENT','ANNULATION')), Quantity INTEGER NOT NULL CHECK(Quantity<>0), OccurredAt TEXT NOT NULL, Reference TEXT, Notes TEXT);
CREATE TABLE IF NOT EXISTS CashSessions (Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL REFERENCES Users(Id), OpenedAt TEXT NOT NULL, ClosedAt TEXT, OpeningCashMinor INTEGER NOT NULL CHECK(OpeningCashMinor>=0), ClosingCashMinor INTEGER CHECK(ClosingCashMinor>=0), Status TEXT NOT NULL CHECK(Status IN ('OUVERTE','FERMEE')));
CREATE TABLE IF NOT EXISTS Sales (Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL REFERENCES Users(Id), CashSessionId INTEGER REFERENCES CashSessions(Id), ReceiptNumber TEXT NOT NULL UNIQUE, SoldAt TEXT NOT NULL, Status TEXT NOT NULL CHECK(Status IN ('VALIDEE','ANNULEE','REMBOURSEE')), TotalMinor INTEGER NOT NULL CHECK(TotalMinor>=0));
CREATE TABLE IF NOT EXISTS SaleLines (Id INTEGER PRIMARY KEY, SaleId INTEGER NOT NULL REFERENCES Sales(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), LotId INTEGER REFERENCES Lots(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), UnitPriceMinor INTEGER NOT NULL CHECK(UnitPriceMinor>=0), LineTotalMinor INTEGER NOT NULL CHECK(LineTotalMinor>=0));
CREATE TABLE IF NOT EXISTS Payments (Id INTEGER PRIMARY KEY, SaleId INTEGER NOT NULL REFERENCES Sales(Id), Method TEXT NOT NULL CHECK(Method IN ('ESPECES','CARTE','MOBILE','AUTRE')), AmountMinor INTEGER NOT NULL CHECK(AmountMinor>0), PaidAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Returns (Id INTEGER PRIMARY KEY, SaleId INTEGER NOT NULL REFERENCES Sales(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), ReturnedAt TEXT NOT NULL, Reason TEXT NOT NULL, Status TEXT NOT NULL CHECK(Status IN ('VALIDEE','ANNULEE')));
CREATE TABLE IF NOT EXISTS ReturnLines (Id INTEGER PRIMARY KEY, ReturnId INTEGER NOT NULL REFERENCES Returns(Id), SaleLineId INTEGER NOT NULL REFERENCES SaleLines(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), AmountMinor INTEGER NOT NULL CHECK(AmountMinor>=0));
CREATE TABLE IF NOT EXISTS CashMovements (Id INTEGER PRIMARY KEY, SessionId INTEGER NOT NULL REFERENCES CashSessions(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), Type TEXT NOT NULL CHECK(Type IN ('ENTREE','SORTIE')), AmountMinor INTEGER NOT NULL CHECK(AmountMinor>0), OccurredAt TEXT NOT NULL, Reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Inventories (Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL REFERENCES Users(Id), StartedAt TEXT NOT NULL, CompletedAt TEXT, Status TEXT NOT NULL CHECK(Status IN ('EN_COURS','TERMINE','ANNULE')));
CREATE TABLE IF NOT EXISTS InventoryLines (Id INTEGER PRIMARY KEY, InventoryId INTEGER NOT NULL REFERENCES Inventories(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), LotId INTEGER REFERENCES Lots(Id), ExpectedQuantity INTEGER NOT NULL CHECK(ExpectedQuantity>=0), CountedQuantity INTEGER CHECK(CountedQuantity>=0), UNIQUE(InventoryId,LotId));
CREATE TABLE IF NOT EXISTS AuditLog (Id INTEGER PRIMARY KEY, UserId INTEGER REFERENCES Users(Id), Action TEXT NOT NULL, Entity TEXT NOT NULL, EntityId INTEGER, OccurredAt TEXT NOT NULL, Details TEXT);
CREATE TABLE IF NOT EXISTS PharmacySettings (Key TEXT PRIMARY KEY, Value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS IX_Products_Name ON Products(Name);
CREATE INDEX IF NOT EXISTS IX_Lots_ProductExpiry ON Lots(ProductId,ExpiryDate);
CREATE INDEX IF NOT EXISTS IX_StockMovements_ProductDate ON StockMovements(ProductId,OccurredAt);
CREATE INDEX IF NOT EXISTS IX_Sales_SoldAt ON Sales(SoldAt);
CREATE INDEX IF NOT EXISTS IX_Sales_Session ON Sales(CashSessionId);
CREATE INDEX IF NOT EXISTS IX_AuditLog_Date ON AuditLog(OccurredAt);
INSERT OR IGNORE INTO SchemaVersions(Version,AppliedAt) VALUES(1,datetime('now'));
""";

    public const string V2 = """
ALTER TABLE Products ADD COLUMN Dosage TEXT NOT NULL DEFAULT '';
ALTER TABLE Products ADD COLUMN PharmaceuticalForm TEXT NOT NULL DEFAULT '';
ALTER TABLE Products ADD COLUMN ShelfLocation TEXT;
ALTER TABLE Lots ADD COLUMN IsBlocked INTEGER NOT NULL DEFAULT 0 CHECK(IsBlocked IN (0,1));
ALTER TABLE Lots ADD COLUMN BlockReason TEXT;
CREATE TABLE IF NOT EXISTS ReceiptLines (Id INTEGER PRIMARY KEY, ReceiptId INTEGER NOT NULL REFERENCES Receipts(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), LotId INTEGER NOT NULL REFERENCES Lots(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), UnitCostMinor INTEGER NOT NULL CHECK(UnitCostMinor>=0));
CREATE TABLE IF NOT EXISTS StockAdjustments (Id INTEGER PRIMARY KEY, ProductId INTEGER NOT NULL REFERENCES Products(Id), LotId INTEGER NOT NULL REFERENCES Lots(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), QuantityDelta INTEGER NOT NULL CHECK(QuantityDelta<>0), Reason TEXT NOT NULL CHECK(length(trim(Reason))>0), OccurredAt TEXT NOT NULL, InventoryId INTEGER REFERENCES Inventories(Id));
CREATE INDEX IF NOT EXISTS IX_Receipts_ReceivedAt ON Receipts(ReceivedAt);
CREATE INDEX IF NOT EXISTS IX_ReceiptLines_Receipt ON ReceiptLines(ReceiptId);
CREATE INDEX IF NOT EXISTS IX_Lots_BlockedExpiry ON Lots(IsBlocked,ExpiryDate);
INSERT OR IGNORE INTO PharmacySettings(Key,Value) VALUES('ExpiryAlertDays','90');
""";

    public const string V3 = """
ALTER TABLE SaleLines ADD COLUMN UnitCostMinor INTEGER NOT NULL DEFAULT 0 CHECK(UnitCostMinor>=0);
ALTER TABLE Sales ADD COLUMN DiscountMinor INTEGER NOT NULL DEFAULT 0 CHECK(DiscountMinor>=0);
ALTER TABLE Payments ADD COLUMN ManualConfirmation TEXT;
CREATE TABLE IF NOT EXISTS SaleLotConsumptions (Id INTEGER PRIMARY KEY, SaleLineId INTEGER NOT NULL REFERENCES SaleLines(Id), LotId INTEGER NOT NULL REFERENCES Lots(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), UnitCostMinor INTEGER NOT NULL CHECK(UnitCostMinor>=0));
CREATE TABLE IF NOT EXISTS SaleReversals (Id INTEGER PRIMARY KEY, SaleId INTEGER NOT NULL REFERENCES Sales(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), Type TEXT NOT NULL CHECK(Type IN ('RETOUR','ANNULATION')), Reason TEXT NOT NULL CHECK(length(trim(Reason))>0), OccurredAt TEXT NOT NULL, RefundMinor INTEGER NOT NULL CHECK(RefundMinor>=0), UNIQUE(SaleId,Type));
CREATE TABLE IF NOT EXISTS SaleReturnLines (Id INTEGER PRIMARY KEY, ReversalId INTEGER NOT NULL REFERENCES SaleReversals(Id), SaleLineId INTEGER NOT NULL REFERENCES SaleLines(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), LotId INTEGER NOT NULL REFERENCES Lots(Id));
CREATE TABLE IF NOT EXISTS CashSessionClosures (Id INTEGER PRIMARY KEY, SessionId INTEGER NOT NULL UNIQUE REFERENCES CashSessions(Id), UserId INTEGER NOT NULL REFERENCES Users(Id), ClosedAt TEXT NOT NULL, CashSalesMinor INTEGER NOT NULL, NonCashSalesMinor INTEGER NOT NULL, ExpectedCashMinor INTEGER NOT NULL, CountedCashMinor INTEGER NOT NULL, DifferenceMinor INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS IX_Sales_UserDate ON Sales(UserId,SoldAt);
CREATE INDEX IF NOT EXISTS IX_Payments_Sale ON Payments(SaleId);
""";

    public const string V4 = """
ALTER TABLE SaleLines ADD COLUMN ProductName TEXT NOT NULL DEFAULT '';
""";

    public const string V5 = """
ALTER TABLE Sales ADD COLUMN IdempotencyKey TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS UX_Sales_IdempotencyKey ON Sales(IdempotencyKey) WHERE IdempotencyKey IS NOT NULL;
""";

    public const string V6 = """
CREATE TRIGGER IF NOT EXISTS TR_AuditLog_NoUpdate BEFORE UPDATE ON AuditLog BEGIN SELECT RAISE(ABORT,'Le journal d’audit est immuable'); END;
CREATE TRIGGER IF NOT EXISTS TR_AuditLog_NoDelete BEFORE DELETE ON AuditLog BEGIN SELECT RAISE(ABORT,'Le journal d’audit est immuable'); END;
INSERT OR IGNORE INTO PharmacySettings(Key,Value) VALUES('BackupTime','23:00'),('BackupDirectory',''),('Currency','XOF'),('TaxesEnabled','0'),('PriceDecimals','0');
""";

    public const string V7 = """
CREATE TRIGGER IF NOT EXISTS TR_StockMovement_Audit AFTER INSERT ON StockMovements BEGIN
 INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES(NEW.UserId,'MOUVEMENT_STOCK','StockMovements',NEW.Id,NEW.OccurredAt,NEW.MovementType||'; quantité='||NEW.Quantity||'; référence='||COALESCE(NEW.Reference,'')||'; motif='||COALESCE(NEW.Notes,''));
END;
CREATE TRIGGER IF NOT EXISTS TR_SaleReversal_Audit AFTER INSERT ON SaleReversals BEGIN
 INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES(NEW.UserId,NEW.Type,'Sales',NEW.SaleId,NEW.OccurredAt,'Motif='||NEW.Reason||'; remboursement='||NEW.RefundMinor);
END;
""";
}
